import type { ReactNode } from "react";
import { useEffect, useMemo, useRef, useState } from "react";

const SEARCH_DEBOUNCE_MS = 400;
/** 一次最多渲染的候选数。cmdk 没有虚拟滚动，超长列表（如 500+ 时区）全量挂载会产生数百 ms 长任务。 */
const MAX_RENDERED_OPTIONS = 100;

export interface ComboboxOption {
  value: string;
  label: ReactNode;
  disabled?: boolean;
}

export interface UseComboboxOptionsResult {
  options: ComboboxOption[];
  /** 因渲染上限被截断的条目数；>0 时 UI 应提示“继续输入以缩小范围”。 */
  truncatedCount: number;
  loading: boolean;
  search: string;
  setSearch: (value: string) => void;
}

/**
 * 静态模式：`options` 本地按 `search` 过滤（label 为 string 时不区分大小写包含，否则不过滤）。
 * 远程模式（传了 `loadOptions`）：`search` 变化防抖 400ms 后调用 `loadOptions`，
 * 结果与 `options`（若给了，视为常驻的"种子"条目，如已选值的已知 label）按 value 去重合并。
 * 种子条目始终在列表中可见，不受当前搜索词过滤，用于回显选中态与做 label 缓存。
 */
export function useComboboxOptions(opts: {
  options?: ComboboxOption[];
  loadOptions?: (search: string) => Promise<ComboboxOption[]>;
}): UseComboboxOptionsResult {
  const { options: staticOptions, loadOptions } = opts;
  const hasLoadOptions = loadOptions !== undefined;
  const loadOptionsRef = useRef(loadOptions);
  loadOptionsRef.current = loadOptions;

  const [search, setSearch] = useState("");
  const [remoteOptions, setRemoteOptions] = useState<ComboboxOption[]>([]);
  const [loading, setLoading] = useState(false);
  const requestId = useRef(0);

  useEffect(() => {
    if (!hasLoadOptions) return;
    const id = ++requestId.current;
    const handle = setTimeout(() => {
      setLoading(true);
      loadOptionsRef.current?.(search).then((result) => {
        if (requestId.current === id) {
          setRemoteOptions(result);
          setLoading(false);
        }
      });
    }, SEARCH_DEBOUNCE_MS);
    return () => clearTimeout(handle);
  }, [search, hasLoadOptions]);

  const { options, truncatedCount } = useMemo(() => {
    let full: ComboboxOption[];
    if (hasLoadOptions) {
      if (!staticOptions || staticOptions.length === 0) {
        full = remoteOptions;
      } else {
        const merged = new Map<string, ComboboxOption>();
        for (const option of staticOptions) merged.set(option.value, option);
        for (const option of remoteOptions) merged.set(option.value, option);
        full = [...merged.values()];
      }
    } else if (!staticOptions) {
      full = [];
    } else {
      const query = search.trim().toLowerCase();
      full = query
        ? staticOptions.filter((option) =>
            typeof option.label === "string" ? option.label.toLowerCase().includes(query) : true,
          )
        : staticOptions;
    }
    if (full.length <= MAX_RENDERED_OPTIONS) return { options: full, truncatedCount: 0 };
    return {
      options: full.slice(0, MAX_RENDERED_OPTIONS),
      truncatedCount: full.length - MAX_RENDERED_OPTIONS,
    };
  }, [hasLoadOptions, staticOptions, remoteOptions, search]);

  return { options, truncatedCount, loading, search, setSearch };
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { useEffect, useRef } from "react";
import {
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
  Combobox as ComboboxRoot,
} from "@/components/ui/combobox";
import { type ComboboxOption, useComboboxOptions } from "./use-combobox-options";

export interface ComboboxProps {
  value: string | undefined;
  onChange: (value: string | undefined) => void;
  options?: ComboboxOption[];
  loadOptions?: (search: string) => Promise<ComboboxOption[]>;
  placeholder?: string;
  disabled?: boolean;
}

function isEqualOption(a: ComboboxOption, b: ComboboxOption): boolean {
  return a.value === b.value;
}

/** 单选 combobox：本地过滤或共享的远程 `loadOptions`（防抖 400ms），选中项 label 靠内部缓存回显。 */
export function Combobox({
  value,
  onChange,
  options,
  loadOptions,
  placeholder,
  disabled,
}: ComboboxProps) {
  const L = useLocalization();
  const {
    options: resolvedOptions,
    truncatedCount,
    loading,
    search,
    setSearch,
  } = useComboboxOptions({ options, loadOptions });

  const cacheRef = useRef(new Map<string, ComboboxOption>());
  for (const option of resolvedOptions) cacheRef.current.set(option.value, option);

  // value 由外部（受控）变化时，把该值已知的 label 同步进搜索框文本，让关闭态的输入框显示选中项。
  useEffect(() => {
    if (value === undefined) return;
    const cached = cacheRef.current.get(value);
    if (cached && typeof cached.label === "string") setSearch(cached.label);
    // setSearch 是 useState setter，引用稳定；只想在受控 value 变化时同步，search/cache 不应触发。
  }, [value, setSearch]);

  const selected =
    value !== undefined ? (cacheRef.current.get(value) ?? { value, label: value }) : null;

  return (
    <ComboboxRoot
      items={resolvedOptions}
      value={selected}
      onValueChange={(next) => {
        onChange(next ? next.value : undefined);
        if (next && typeof next.label === "string") setSearch(next.label);
      }}
      inputValue={search}
      onInputValueChange={setSearch}
      isItemEqualToValue={isEqualOption}
      filter={null}
      disabled={disabled}
    >
      <ComboboxInput placeholder={placeholder ?? L("Combobox:Placeholder")} disabled={disabled} />
      <ComboboxContent>
        <ComboboxList>
          {(option: ComboboxOption) => (
            <ComboboxItem key={option.value} value={option} disabled={option.disabled}>
              {option.label}
            </ComboboxItem>
          )}
        </ComboboxList>
        {truncatedCount > 0 && (
          <div className="border-t py-1.5 text-center text-xs text-muted-foreground">
            {L("Combobox:Truncated", truncatedCount)}
          </div>
        )}
        {loading ? (
          <div className="py-2 text-center text-sm text-muted-foreground">
            {L("Combobox:Loading")}
          </div>
        ) : (
          <ComboboxEmpty>{L("Combobox:Empty")}</ComboboxEmpty>
        )}
      </ComboboxContent>
    </ComboboxRoot>
  );
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { useRef } from "react";
import {
  ComboboxChip,
  ComboboxChips,
  ComboboxChipsInput,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxItem,
  ComboboxList,
  Combobox as ComboboxRoot,
  useComboboxAnchor,
} from "@/components/ui/combobox";
import { type ComboboxOption, useComboboxOptions } from "./use-combobox-options";

export interface MultiComboboxProps {
  values: string[];
  onChange: (values: string[]) => void;
  options?: ComboboxOption[];
  loadOptions?: (search: string) => Promise<ComboboxOption[]>;
  placeholder?: string;
  disabled?: boolean;
}

function isEqualOption(a: ComboboxOption, b: ComboboxOption): boolean {
  return a.value === b.value;
}

/**
 * 多选 combobox：与单选共享同一个 `useComboboxOptions`（本地过滤或远程 `loadOptions`）。
 * 已选项 label 靠 `knownRef` 跨渲染累积缓存。远程模式下搜索词变化会替换当前结果集，
 * 但已经出现过的选项（含已选中的）label 留在缓存里，喂回 `useComboboxOptions` 的 `options`
 * 种子参数，chips 因此不会因为搜索词变化而丢失 label。
 */
export function MultiCombobox({
  values,
  onChange,
  options,
  loadOptions,
  placeholder,
  disabled,
}: MultiComboboxProps) {
  const L = useLocalization();
  const knownRef = useRef(new Map<string, ComboboxOption>());
  for (const option of options ?? []) knownRef.current.set(option.value, option);

  const seed = values
    .map((v) => knownRef.current.get(v))
    .filter((o): o is ComboboxOption => o !== undefined);

  const {
    options: resolvedOptions,
    truncatedCount,
    loading,
    search,
    setSearch,
  } = useComboboxOptions({ options: loadOptions ? seed : options, loadOptions });

  for (const option of resolvedOptions) knownRef.current.set(option.value, option);

  const selectedOptions = values.map((v) => knownRef.current.get(v) ?? { value: v, label: v });
  const anchor = useComboboxAnchor();

  return (
    <ComboboxRoot
      multiple
      items={resolvedOptions}
      value={selectedOptions}
      onValueChange={(next) => onChange(next.map((o) => o.value))}
      inputValue={search}
      onInputValueChange={setSearch}
      isItemEqualToValue={isEqualOption}
      filter={null}
      disabled={disabled}
    >
      <div ref={anchor}>
        <ComboboxChips>
          {selectedOptions.map((option) => (
            <ComboboxChip key={option.value}>{option.label}</ComboboxChip>
          ))}
          <ComboboxChipsInput
            placeholder={
              selectedOptions.length > 0 ? undefined : (placeholder ?? L("Combobox:Search"))
            }
            disabled={disabled}
          />
        </ComboboxChips>
      </div>
      <ComboboxContent anchor={anchor}>
        <ComboboxList>
          {(option: ComboboxOption) => (
            <ComboboxItem key={option.value} value={option} disabled={option.disabled}>
              {option.label}
            </ComboboxItem>
          )}
        </ComboboxList>
        {truncatedCount > 0 && (
          <div className="border-t py-1.5 text-center text-xs text-muted-foreground">
            {L("Combobox:Truncated", truncatedCount)}
          </div>
        )}
        {loading ? (
          <div className="py-2 text-center text-sm text-muted-foreground">
            {L("Combobox:Loading")}
          </div>
        ) : (
          <ComboboxEmpty>{L("Combobox:Empty")}</ComboboxEmpty>
        )}
      </ComboboxContent>
    </ComboboxRoot>
  );
}

